package com.estoqueinteligente.auth;import jakarta.validation.constraints.*;public class LoginRequest{@NotBlank(message="O e-mail é obrigatório")@Email(message="Informe um e-mail válido")private String email;@NotBlank(message="A senha é obrigatória")private String password;public LoginRequest(){}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}}
